from research_helpers import *
I=ev('https://www.immupharma.co.uk/investors/','Current issuer pipeline identifies P140, Type M Diagnostic Platform, Kapiglucagon, BioAMB and BioCIN; none represented as approved therapies.')
IH=ev('https://www.immupharma.co.uk/wp-content/uploads/2025/10/ImmuPharma-Annual-Report-2013.pdf','Historical 2013 report identifies IPP-102199, IPP-201007, IPP-203101 and IPP-204106; upload path does not change report year.')
IN=ev('https://www.immupharma.co.uk/2012/10/08/cancer-programme-ipp-204106-progresses-clinical-trials-first-cancer-patients-new-trial-begin-dosing/','Polyplexed Nucant combines IPP-204106 with specific excipient in distinct formulation; retained separately from underlying candidate.')
IU=ev('https://www.immupharma.co.uk/wp-content/uploads/2020/09/IMM-Information-Note-Euronext-Updated-30-Sep-2020.pdf','Historical issuer documents Urelix and PDCT peptide drug-development technologies. BioGlucagon identity versus later Kapiglucagon unresolved, not duplicated.')
IP=ev('https://www.immupharma.co.uk/science/autoimmunity/p140/','Official page equates P140, Lupuzor and forigerimod.')
ip=[p('P140','Investigational immune-modulating peptide.',IP,'development',aliases=['Lupuzor','Forigerimod']),p('Type M Diagnostic Platform','Investigational companion diagnostic platform for autoimmune disease.',I,'development',typ='technology',sub='diagnostics'),p('Kapiglucagon','Investigational glucagon prodrug.',ev('https://www.immupharma.co.uk/science/type-1-diabetes/kapiglucagon/','Issuer describes glucagon prodrug; not competitor dasiglucagon.'),'research'),p('BioAMB','Investigational amphotericin B-based antifungal therapeutic.',ev('https://www.immupharma.co.uk/science/anti-infectives/bioamb/','Amphotericin B-releasing investigational candidate.'),'research'),p('BioCIN','Investigational vancomycin-based antibacterial formulation.',ev('https://www.immupharma.co.uk/science/anti-infectives/biocin/','Next-generation vancomycin-based formulation.'),'research')]
for name,desc in [('IPP-102199','Historical peptide program for moderate to severe pain.'),('IPP-201007','Historical inflammatory and allergic disease program targeting phospholipase A2.'),('IPP-203101','Historical antibacterial peptide development program.'),('IPP-204106','Historical nucleolin-targeting anticancer candidate.')]:ip.append(p(name,desc,IH,aliases=['N6L'] if name=='IPP-204106' else []))
ip += [p('Polyplexed Nucant','Historical formulated IPP-204106 with specific excipient.',IN,typ='development_program'),p('PDCT','Peptide-to-drug converting technology.',IU,typ='technology'),p('Urelix','Peptide drug-discovery technology platform.',IU,typ='technology')]
C=ev('https://www.sec.gov/Archives/edgar/data/1522602/000121390021041377/ea145151ex99-1_cohbar.htm','2021 issuer describes named mitochondrial therapeutic leads and research programs; historical evidence does not establish current active development.')
CF=ev('https://www.sec.gov/Archives/edgar/data/1522602/000121390021041999/f10q0621_cohbarinc.htm','Issuer enumerates CB4211, CB5138-3, CB5064 analogs, CB5046 analogs and MBT3 analogs; analog research programs not fabricated as specific molecular candidates.')
CT=ev('https://www.sec.gov/Archives/edgar/data/1498382/000119312525069713/d888264d425.htm','Successor issuer confirms proposed CohBar merger was terminated; Morphogenesis/TuHURA products not attributed to CohBar.')
cp=[p(n,d,CF) for n,d in [('CB4211','Historical mitochondrial peptide therapeutic candidate for NASH and obesity.'),('CB5138-3','Historical mitochondrial peptide therapeutic candidate for idiopathic pulmonary fibrosis.'),('CB5064 analogs','Historical mitochondrial peptide analog research program for lung injury.'),('CB5046 analogs','Historical CXCR4-related mitochondrial peptide anticancer research program.'),('MBT3 analogs','Historical mitochondrial peptide analog cancer immunotherapy research program.')]]
O=ev('https://www.sec.gov/Archives/edgar/data/1717452/000156459021015499/odt-8k_20210319.htm','Issuer explicitly discontinued tesetaxel development and announced wind-down in March 2021.')
OL=ev('https://www.sec.gov/Archives/edgar/data/1717452/000156459021056269/odt-10q_20210930.htm','Issuer describes oral taxane tesetaxel licensed from Daiichi Sankyo; developer/licensee roles do not assert original invention or current ownership.')
companies=[company('IMMUPHARMA PLC LS-01',ip,[I,IH,IN,IU,IP],'Current five programs plus named historical candidates and technologies reviewed. BioGlucagon/Kapiglucagon identity, legacy licensing and formulation chronology remain unresolved.'),company('CohBar Inc',cp,[C,CF,CT],'Five named historical leads/programs reviewed. Latest rights and development status require further reconciliation; terminated merger not treated as acquisition.'),company('Odonate Therapeutics Inc',[p('Tesetaxel','Oral taxane anticancer development candidate, discontinued by Odonate in 2021.',O,'discontinued',roles=['developer','licensee'],evidence=[O,OL])],[O,OL],'Historical single-asset portfolio and explicit discontinuation reviewed; subsequent rights disposition and latest corporate records remain unresolved.')]
(out/'batch-0013.json').write_text(json.dumps({'companies':companies},indent=2))
